import React from "react";
import AdForm from "./components/AddForm";

export default function App(): React.ReactElement {
  return (
    <div
      style={{
        background: "#F3F4F6",
        minHeight: "100", // Ensure the container takes full height
        width: "100%", // Full width of the page
        display: "flex", // Flexbox to help stretch content
        flexDirection: "column", // Ensures children stack vertically
      }}
    >
      <div
        style={{
          width: "100%", // Full width of the container
          height: "5rem", // Fixed height for this section
          background: "white",
        }}
      >
        <img
          src="/logoAutos.jpeg" // Change this to the actual image path
          alt="Header Image"
          style={{
            margin: 10,
            height: "auto",
          }}
        />
      </div>
      <AdForm />
    </div>
  );
}
